using Purview.BuildSdk.Harness;
using Purview.BuildSdk.Infra;

namespace Purview.BuildSdk;

/// <summary>
/// Verifies the auto-generated assembly identifier marker class architecture tests use to
/// pin an assembly by type instead of by name.
/// </summary>
sealed class GeneratedAssemblyIdentifierTests
{
	// The telemetry and SourceLink packages are irrelevant to these scenarios and only slow
	// restore down, so they are removed the same way GeneratedAssemblyInfoTests does.
	const string RemoveUnrelatedPackages = """
		<PackageReference Remove="Purview.Telemetry.SourceGenerator" />
		<PackageReference Remove="Microsoft.Extensions.Telemetry.Abstractions" />
		<PackageReference Remove="Microsoft.SourceLink.GitHub" />
		""";

	[Test]
	public async Task GeneratedAssemblyIdentifier_ForProductionProject_BuildsAndDeclaresMarkerClass(
		CancellationToken cancellationToken
	)
	{
		using var h = await ProjectHarness.CreateAsync(
			"MyLibrary",
			extraItems: RemoveUnrelatedPackages,
			cancellationToken: cancellationToken
		);

		var (success, output, errors) = await h.BuildAsync(restore: true, cancellationToken: cancellationToken);
		await Assert.That(success).IsTrue().Because(TestHelpers.GenerateError(output, errors));

		var generatedFiles = Directory.GetFiles(
			h.ProjectDirectory,
			"GeneratedAssemblyIdentifier.cs",
			SearchOption.AllDirectories
		);
		await Assert.That(generatedFiles.Length).IsEqualTo(1);

		var content = await File.ReadAllTextAsync(generatedFiles[0], cancellationToken);

		await Assert.That(content).Contains("public static partial class MyLibraryAssembly");
		await Assert.That(content).Contains("// <auto-generated />");
		await Assert.That(content).Contains("/// <summary>");
	}

	[Test]
	public async Task GeneratedAssemblyIdentifier_WithNamespacePrefixedProjectName_StripsPrefixAndDots(
		CancellationToken cancellationToken
	)
	{
		using var h = await ProjectHarness.CreateAsync(
			"Test.Core.Abstractions",
			extraItems: RemoveUnrelatedPackages,
			cancellationToken: cancellationToken
		);

		var (success, output, errors) = await h.BuildAsync(restore: true, cancellationToken: cancellationToken);
		await Assert.That(success).IsTrue().Because(TestHelpers.GenerateError(output, errors));

		var generatedFiles = Directory.GetFiles(
			h.ProjectDirectory,
			"GeneratedAssemblyIdentifier.cs",
			SearchOption.AllDirectories
		);
		await Assert.That(generatedFiles.Length).IsEqualTo(1);

		var content = await File.ReadAllTextAsync(generatedFiles[0], cancellationToken);

		await Assert.That(content).Contains("public static partial class CoreAbstractionsAssembly");
	}

	[Test]
	public async Task GeneratedAssemblyIdentifier_WhenDisabled_GeneratesNothing(CancellationToken cancellationToken)
	{
		using var h = await ProjectHarness.CreateAsync(
			"MyLibrary",
			extraProps: "<DisableGenerateAssemblyIdentifierClass>true</DisableGenerateAssemblyIdentifierClass>",
			extraItems: RemoveUnrelatedPackages,
			cancellationToken: cancellationToken
		);

		var (success, output, errors) = await h.BuildAsync(restore: true, cancellationToken: cancellationToken);
		await Assert.That(success).IsTrue().Because(TestHelpers.GenerateError(output, errors));

		var generatedFiles = Directory.GetFiles(
			h.ProjectDirectory,
			"GeneratedAssemblyIdentifier.cs",
			SearchOption.AllDirectories
		);
		await Assert.That(generatedFiles.Length).IsEqualTo(0);
	}

	[Test]
	public async Task GeneratedAssemblyIdentifier_ForTestProject_IsDisabledByDefault(
		CancellationToken cancellationToken
	)
	{
		using var h = await ProjectHarness.CreateAsync("MyLibrary.UnitTests", cancellationToken: cancellationToken);

		var disabled = await h.GetPropertyAsync("DisableGenerateAssemblyIdentifierClass", cancellationToken);

		await Assert.That(disabled).IsEqualTo("true");
	}
}
